import type { GetServerSideProps } from 'next';
import { getPost } from '@/lib/posts';

const RETIRED = new Set(['old-post']); // paths removed with no successor

export const getServerSideProps: GetServerSideProps<{ title?: string; gone?: boolean }> = async ({ params, res }) => {
  const slug = String(params?.slug ?? '');
  if (RETIRED.has(slug)) {
    res.statusCode = 410; // RTE-004: retired path
    return { props: { gone: true } };
  }
  const post = await getPost(slug); // a database error throws -> pages/500.tsx with status 500
  if (!post) return { notFound: true }; // RTE-005/006: 404 before render
  return { props: { title: post.title } };
};

export default function BlogPost({ title, gone }: { title?: string; gone?: boolean }) {
  if (gone) return <main><h1>This article has been removed</h1></main>;
  return <article><h1>{title}</h1></article>;
}
