import { db } from '@/lib/db'; // your data client
export async function getPost(slug: string) {
  // No try/catch that returns null: a connection error must propagate so Next answers 5xx.
  const rows = await db.query('select id, title from posts where slug = $1', [slug]);
  return rows[0] ?? null;
}

Next.js Pages Router (15/16). A plain HTML form posting to an API route: it works without JavaScript, redirects (303) to a thank-you state only after the downstream call succeeded, and answers 502 when delivery fails. Set SITE_URL and FORM_WEBHOOK_URL (your CRM, form provider or mail API; for email use your provider's HTTPS API the same way). The in-memory limiter is per instance: use Redis/Upstash when you run several. Add Cloudflare Turnstile (`cf-turnstile-response`, verified server-side) if bots get past the honeypot.
