import type { GetServerSideProps } from 'next';
import Link from 'next/link';

export const getServerSideProps: GetServerSideProps<{ sent: boolean }> = async ({ query }) => ({ props: { sent: query.sent === '1' } });

export default function Contact({ sent }: { sent: boolean }) {
  if (sent) return <main><h1>Thanks, your message was sent.</h1></main>;
  return (
    <main>
      <h1>Contact us</h1>
      <form method="post" action="/api/contact">
        <label>Name <input name="name" autoComplete="name" required maxLength={100} /></label>
        <label>Email <input type="email" name="email" autoComplete="email" required maxLength={254} /></label>
        <label>Message <textarea name="message" required maxLength={5000} /></label>
        {/* honeypot (SEC-055): not type=hidden, hidden by CSS; real users never fill it */}
        <div className="hp" aria-hidden="true">
          <label>Leave this empty <input name="website" tabIndex={-1} autoComplete="off" /></label>
        </div>
        <p>We use your details only to reply. <Link href="/privacy">Privacy notice</Link></p> {/* PRV-028 */}
        <button type="submit">Send</button>
      </form>
    </main>
  );
}
