import type { NextApiRequest, NextApiResponse } from 'next';

const siteOrigin = new URL(process.env.SITE_URL ?? 'https://example.com').origin;
const hits = new Map<string, number[]>();

function rateLimited(ip: string): boolean {
  const now = Date.now();
  const recent = (hits.get(ip) ?? []).filter((t) => now - t < 10 * 60_000);
  recent.push(now);
  hits.set(ip, recent);
  return recent.length > 5; // SEC-054: more than 5 per 10 minutes -> 429
}

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return res.status(405).setHeader('Allow', 'POST').end();

  // SEC-024: same-origin only (Origin, else Sec-Fetch-Site)
  const origin = req.headers.origin;
  if (origin ? origin !== siteOrigin : req.headers['sec-fetch-site'] === 'cross-site') return res.status(403).end('Forbidden');

  const ip = String(req.headers['x-forwarded-for'] ?? req.socket.remoteAddress ?? 'unknown').split(',')[0].trim(); // trust only behind your own proxy
  if (rateLimited(ip)) return res.status(429).setHeader('Retry-After', '600').end('Too many requests');

  const body = (req.body ?? {}) as Record<string, unknown>; // urlencoded form fields
  if (String(body.website ?? '') !== '') return res.redirect(303, '/contact?sent=1'); // honeypot filled: look successful, do nothing

  const name = String(body.name ?? '').trim();
  const email = String(body.email ?? '').trim();
  const message = String(body.message ?? '').trim();
  if (!name || name.length > 100 || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email) || email.length > 254 || !message || message.length > 5000) {
    return res.status(400).end('Invalid form');
  }

  try {
    const upstream = await fetch(process.env.FORM_WEBHOOK_URL!, { // the real destination (UX-001); replace with your provider call
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name, email, message }),
      signal: AbortSignal.timeout(8000),
    });
    if (!upstream.ok) throw new Error(`webhook ${upstream.status}`);
  } catch {
    // RES-008: delivery failed -> a 5xx page, never the success state
    res.status(502).setHeader('Content-Type', 'text/html; charset=utf-8');
    return res.end('<!doctype html><html lang="en"><title>Message not sent</title><body><nav><a href="/">Home</a></nav><h1>Your message was not sent</h1><p>Please try again later.</p></body></html>');
  }
  return res.redirect(303, '/contact?sent=1');
}

Next.js Pages Router (15/16). Nonce CSP: proxy.ts (middleware.ts on Next 15, export `middleware`) generates the nonce and sets the policy; pages/_document.tsx passes the nonce to <Head> and <NextScript> (Next docs). MEASURED on Next 16.4.2: reading the nonce in _document alone does NOT make pages dynamic. Pages without getServerSideProps are still prerendered at build, their HTML carries no nonce and `strict-dynamic` then blocks every script. The _app.getInitialProps line below switches automatic static optimisation off (Next docs: a custom App getInitialProps disables it for pages without getStaticProps), so every page is rendered per request (no ISR, no static export). Next already sends `Cache-Control: public, max-age=31536000, immutable` for hashed /_next/static assets (it cannot be overridden); only your own fingerprinted files need a rule.
### file: proxy.ts
import { NextResponse, type NextRequest } from 'next/server';

export function proxy(request: NextRequest) {
  const nonce = Buffer.from(crypto.randomUUID()).toString('base64'); // fresh per response
  const dev = process.env.NODE_ENV === 'development';
  const csp = [
    "default-src 'self'",
    // SEC-075: nonce + strict-dynamic; no wildcard, no unsafe-inline for scripts
    `script-src 'self' 'nonce-${nonce}' 'strict-dynamic'${dev ? " 'unsafe-eval'" : ''}`,
    `style-src 'self' ${dev ? "'unsafe-inline'" : `'nonce-${nonce}'`}`,
    "img-src 'self' blob: data:",
    "font-src 'self'",
    "connect-src 'self'", // with analytics add: https://www.google-analytics.com https://*.google-analytics.com https://*.analytics.google.com
    "object-src 'none'",
    "base-uri 'self'",
    "form-action 'self'",
    "frame-ancestors 'none'",
    'upgrade-insecure-requests',
  ].join('; ');

  const requestHeaders = new Headers(request.headers);
  requestHeaders.set('x-nonce', nonce);
  requestHeaders.set('Content-Security-Policy', csp);
  const response = NextResponse.next({ request: { headers: requestHeaders } });
  response.headers.set('Content-Security-Policy', csp);
  return response;
}

export const config = {
  matcher: [
    {
      source: '/((?!api|_next/static|_next/image|favicon.ico).*)',
      missing: [
        { type: 'header', key: 'next-router-prefetch' },
        { type: 'header', key: 'purpose', value: 'prefetch' },
      ],
    },
  ],
};
