import type { NextConfig } from 'next';

const nonProduction = process.env.DEPLOY_ENV !== 'production';

const config: NextConfig = {
  poweredByHeader: false,
  async headers() {
    return [
      {
        source: '/(.*)',
        headers: [
          { key: 'X-Content-Type-Options', value: 'nosniff' },
          { key: 'Referrer-Policy', value: 'strict-origin-when-cross-origin' },
          { key: 'Permissions-Policy', value: 'camera=(), microphone=(), geolocation=()' },
          { key: 'Strict-Transport-Security', value: 'max-age=63072000; includeSubDomains' }, // HTTPS deployments only
        ],
      },
      // PRF-008: only for files YOU fingerprint (content hash in the name) under public/assets/
      {
        source: '/assets/:path*',
        headers: [{ key: 'Cache-Control', value: 'public, max-age=31536000, immutable' }],
      },
      ...(nonProduction
        ? [{ source: '/(.*)', headers: [{ key: 'X-Robots-Tag', value: 'noindex, nofollow' }] }] // IDX-005
        : []),
    ];
  },
};

export default config;

Next.js Pages Router (15/16). API routes always run per request. Replace `db` with the project's data client; keep the contract: 200 when the database answers, 503 when it does not, and nothing but the status word in the body (OPS-002: no versions, commit, dependency or engine names, no error text).
### file: pages/api/health.ts
import type { NextApiRequest, NextApiResponse } from 'next';
import { db } from '@/lib/db'; // your data client

async function databaseUp(): Promise<boolean> {
  try {
    await Promise.race([
      db.query('select 1'),
      new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), 2000)),
    ]);
    return true;
  } catch {
    return false; // never echo the error: it can carry hostnames and versions
  }
}

export default async function handler(_req: NextApiRequest, res: NextApiResponse<{ status: string }>) {
  res.setHeader('Cache-Control', 'no-store');
  if (await databaseUp()) return res.status(200).json({ status: 'ok' });
  return res.status(503).json({ status: 'unavailable' });
}

Next.js Pages Router (15/16) has no robots/sitemap file convention: serve both from API routes and map the public URLs with rewrites. Mode comes from DEPLOY_ENV only (`production` is the one production value). Delete any public/robots.txt and public/sitemap.xml (static files win over rewrites). Non-production: Disallow: /, no Sitemap line, /sitemap.xml answers 404, and X-Robots-Tag: noindex, nofollow on every response (the next.config.ts headers() block of the headers recipe reads DEPLOY_ENV at build time, so rebuild per environment). Above 50,000 URLs split into several files and serve a sitemap index.
