import type { NextApiRequest, NextApiResponse } from 'next';
import { isProduction, siteUrl } from '@/lib/site';

export default function handler(_req: NextApiRequest, res: NextApiResponse) {
  res.setHeader('Content-Type', 'text/plain; charset=utf-8');
  if (!isProduction) return res.status(200).send('User-agent: *\nDisallow: /\n'); // IDX-005
  // IDX-004: only app/API paths are disallowed; /_next/ (CSS/JS) and images stay crawlable
  return res.status(200).send(`User-agent: *\nAllow: /\nDisallow: /api/\nDisallow: /account/\n\nSitemap: ${siteUrl}/sitemap.xml\n`);
}
