import type { NextApiRequest, NextApiResponse } from 'next';
import { isProduction, siteUrl } from '@/lib/site';
import { getIndexablePosts } from '@/lib/posts'; // only pages that answer 200, are self-canonical and not noindex (IDX-001)

const esc = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&apos;');

export default async function handler(_req: NextApiRequest, res: NextApiResponse) {
  if (!isProduction) return res.status(404).end(); // IDX-005: no sitemap outside production
  const posts = await getIndexablePosts();
  const urls = [`${siteUrl}/`, `${siteUrl}/blog`, ...posts.map((p: { slug: string }) => `${siteUrl}/blog/${p.slug}`)]; // same canonical form as the <link rel="canonical"> tags
  const xml = `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${urls.map((u) => `  <url><loc>${esc(u)}</loc></url>`).join('\n')}\n</urlset>\n`;
  res.setHeader('Content-Type', 'application/xml; charset=utf-8');
  res.setHeader('Cache-Control', 'public, max-age=0, must-revalidate');
  return res.status(200).send(xml);
}
